// TEMP-REFERENCE-PHOTOS: stand-in photos hotlinked from the reference marketplace
// (generated by mint-more-backend/scripts/catalogue/extract-reference-photos.js).
// They only fill slots that have no photo of our own (cover_url, gallery,
// categories.icon_url), so uploading ours replaces them one by one.
// Before going live: set USE_REFERENCE_PHOTOS to false, or delete this file,
// referencePhotos.json and the script.
import photos from './referencePhotos.json'
import videos from './referenceVideos.json'

export const USE_REFERENCE_PHOTOS = true

export const referenceCover = (slug) => (USE_REFERENCE_PHOTOS ? photos.services[slug]?.cover || null : null)

export const referenceGallery = (slug) => (USE_REFERENCE_PHOTOS ? photos.services[slug]?.gallery || [] : [])

/** Full-tile artwork ({ desktop, mobile }) for a category. */
export const referenceCategoryTile = (slug) => (USE_REFERENCE_PHOTOS ? photos.categories[slug] || null : null)

// TEMP-REFERENCE-VIDEOS: work-sample reels hotlinked from the reference marketplace's
// home page (generated by mint-more-backend/scripts/catalogue/extract-reference-videos.js).
// Home page only. Before going live: set USE_REFERENCE_VIDEOS to false, or delete
// referenceVideos.json and the script.

export const USE_REFERENCE_VIDEOS = true

export const referenceVideos = () => (USE_REFERENCE_VIDEOS ? videos.videos : [])
